() => {
  // Find the color swatches in the filter
  const colorSection = document.querySelectorAll('[data-csa-c-asin] a[role="link"]');
  const colors = [];
  document.querySelectorAll('ul[aria-labelledby*="p_36"] li a, span.a-list-item a span').forEach((el, i) => {
    const text = el.textContent?.trim();
    if (text && (text.toLowerCase().includes('black') || text.toLowerCase().includes('color'))) {
      colors.push(text);
    }
  });

  // Look for color swatches with aria-labels
  const colorSwatches = [];
  document.querySelectorAll('a[aria-label*="color" i], a[aria-label*="Apply"]').forEach((el) => {
    const ariaLabel = el.getAttribute('aria-label');
    if (ariaLabel && (ariaLabel.toLowerCase().includes('black') || ariaLabel.toLowerCase().includes('color'))) {
      colorSwatches.push(ariaLabel);
    }
  });

  return { colors, colorSwatches: colorSwatches.slice(0, 30) };
}

() => {
  // Find color filter swatches
  const colorFilter = document.querySelector('#filter-p_36\\:p_36_size_value, [id*="p_n_color"]') || document.querySelector('div[id*="color"]');

  // Look at color swatches in the left panel
  const colorSpans = document.querySelectorAll('div[aria-labelledby*="color"] a, [id*="n-color"] a, [id*="n_p_n_color"] a');
  const colorInfo = [];

  // Look for color filters with images of black
  const allSwatches = document.querySelectorAll('img[alt*="Black"], img[alt*="black"], a[aria-label*="Black"], a[aria-label*="black"]');
  allSwatches.forEach(el => {
    colorInfo.push({
      tag: el.tagName,
      alt: el.alt || el.getAttribute('aria-label'),
      index: el.getAttribute('data-csa-c-index') || el.getAttribute('data-hveid')
    });
  });

  // Try direct search of black color links
  const links = document.querySelectorAll('a');
  const blackLinks = [];
  links.forEach(link => {
    const text = link.textContent.trim();
    const ariaLabel = link.getAttribute('aria-label') || '';
    if ((text.toLowerCase() === 'black' || ariaLabel.toLowerCase().includes('black')) && 
        (ariaLabel.toLowerCase().includes('color') || ariaLabel.toLowerCase().includes('narrow'))) {
      blackLinks.push({
        text: text,
        ariaLabel: ariaLabel,
        href: link.href.substring(0, 200)
      });
    }
  });

  return { swatches: colorInfo, blackLinks: blackLinks };
}

