() => {
  // Find the parent anchor of the color swatch view:hdcci
  const allAnchors = document.querySelectorAll('a');
  const colorAnchors = [];
  allAnchors.forEach(a => {
    const child = a.querySelector('[id*="hdcci"], [data-id*="hdcci"], div[style*="background"]');
    if (child || a.id.includes('hdcci') || (a.getAttribute('aria-label') && a.getAttribute('aria-label').toLowerCase().includes('black'))) {
      colorAnchors.push({
        href: a.href.substring(0, 300),
        ariaLabel: a.getAttribute('aria-label') || '',
        text: a.textContent.trim().substring(0, 50)
      });
    }
  });

  // Also look for divs with id hdcci
  const targetDiv = document.querySelector('[data-id="hdcci"], [id*="hdcci"]');
  let parentAnchor = null;
  if (targetDiv) {
    let parent = targetDiv.parentElement;
    while (parent && parent.tagName !== 'A' && parent.tagName !== 'HTML') {
      parent = parent.parentElement;
    }
    if (parent && parent.tagName === 'A') {
      parentAnchor = parent.href;
    }
  }

  return {
    colorAnchors: colorAnchors.slice(0, 5),
    targetDivFound: !!targetDiv,
    parentAnchorHref: parentAnchor ? parentAnchor.substring(0, 300) : null
  };
}

