() => {
  // Find the price slider inputs
  const lower = document.getElementById('p_36/range-slider_slider-item_lower-bound-slider');
  const upper = document.getElementById('p_36/range-slider_slider-item_upper-bound-slider');

  if (!lower || !upper) {
    return { error: 'Slider inputs not found', lower: !!lower, upper: !!upper };
  }

  return {
    lowerMin: lower.min, lowerMax: lower.max, lowerValue: lower.value,
    upperMin: upper.min, upperMax: upper.max, upperValue: upper.value,
    lowerAriaValue: lower.getAttribute('aria-valuetext'),
    upperAriaValue: upper.getAttribute('aria-valuetext')
  };
}

() => {
  // Set the slider values directly via JavaScript and trigger change events
  const lower = document.getElementById('p_36/range-slider_slider-item_lower-bound-slider');
  const upper = document.getElementById('p_36/range-slider_slider-item_upper-bound-slider');

  if (!lower || !upper) {
    return { error: 'Slider inputs not found' };
  }

  // Find a price that maps to ~$25 for lower bound
  // The current upper bound value 24 = $25, so 1 unit ≈ $1
  // Set upper bound first to give room for lower bound
  upper.value = '48';  // ~$50
  upper.setAttribute('aria-valuenow', '48');

  lower.value = '24';  // ~$25
  lower.setAttribute('aria-valuenow', '24');

  // Dispatch change events to trigger the filter
  lower.dispatchEvent(new Event('input', { bubbles: true }));
  lower.dispatchEvent(new Event('change', { bubbles: true }));
  upper.dispatchEvent(new Event('input', { bubbles: true }));
  upper.dispatchEvent(new Event('change', { bubbles: true }));

  return {
    lowerValue: lower.value,
    upperValue: upper.value,
    lowerAriaValue: lower.getAttribute('aria-valuetext'),
    upperAriaValue: upper.getAttribute('aria-valuetext')
  };
}

