() => {
  const lower = document.getElementById('p_36/range-slider_slider-item_lower-bound-slider');
  const upper = document.getElementById('p_36/range-slider_slider-item_upper-bound-slider');

  if (!lower || !upper) return { error: 'Sliders not found' };

  // Set upper bound first to a higher value to allow lower bound to reach $25
  upper.value = '19';  // approximately $50
  upper.setAttribute('aria-valuenow', '19');
  upper.setAttribute('aria-valuetext', '$50');

  // Set lower bound to $25 (about 10/109 * 285 ≈ $26)
  lower.value = '10';
  lower.setAttribute('aria-valuenow', '10');
  lower.setAttribute('aria-valuetext', '$25');

  // Dispatch input events
  lower.dispatchEvent(new Event('input', { bubbles: true }));
  upper.dispatchEvent(new Event('input', { bubbles: true }));

  return {
    lower: lower.value,
    upper: upper.value,
    lowerAria: lower.getAttribute('aria-valuetext'),
    upperAria: upper.getAttribute('aria-valuetext')
  };
}
